SELECT ?zone ?sensor ?ref WHERE {
  ?zone a brick:HVAC_Zone ; brick:hasPoint ?sensor .
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor ref:hasExternalReference ?ref .
}

SELECT ?zone ?label ?sensor ?ref WHERE {
  ?zone a brick:HVAC_Zone ; brick:hasPoint ?sensor .
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?sensor ref:hasExternalReference ?ref .
  OPTIONAL { ?zone rdfs:label ?label }
}

SELECT ?room ?sensor ?ref WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01> brick:hasPart ?room .
  ?room brick:hasPoint ?sensor .
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor ref:hasExternalReference ?ref .
}

